import _ from 'lodash';
import { Award, BarChart3, Book, BookOpen, Calendar, ChevronLeft, ChevronRight, Clock, Library, Star } from 'lucide-react';
import React, { useEffect, useState } from 'react';

// Base components with dark mode support
const ThemedSection = ({ title, icon: Icon, children }) => (
  <section id="literary-odyssey" className="mb-16">
    <h2 className="text-3xl font-bold text-gray-800 dark:text-slate-50 mb-6 flex items-center gap-2">
      <Icon className="w-8 h-8 text-purple-600 dark:text-violet-400" />
      {title}
    </h2>
    {children}
  </section>
);

const ThemedCard = ({ title, subtitle, icon: Icon, children, className = "" }) => (
  <div className={`bg-gradient-to-br from-purple-50 to-indigo-50 dark:from-slate-800/90 dark:to-slate-900/90 rounded-lg shadow-md dark:shadow-lg dark:shadow-slate-900/50 p-6 hover:shadow-lg transition-all duration-300 ${className}`}>
    <div className="flex items-center gap-2 mb-4">
      <div className="p-2 bg-purple-100 dark:bg-violet-500/20 rounded-lg">
        <Icon className="w-6 h-6 text-purple-600 dark:text-violet-400" />
      </div>
      <div>
        <h3 className="text-xl font-semibold text-gray-800 dark:text-slate-50">{title}</h3>
        {subtitle && <p className="text-gray-600 dark:text-slate-300">{subtitle}</p>}
      </div>
    </div>
    {children}
  </div>
);

const StatsCard = ({ icon: Icon, value, label }) => (
  <div className="bg-white dark:bg-slate-800/50 rounded-lg p-4 text-center shadow-sm hover:shadow-md transition-shadow border border-purple-100 dark:border-violet-500/20 backdrop-blur-sm">
    <div className="flex justify-center text-purple-600 dark:text-violet-400 mb-2">
      <Icon className="w-6 h-6" />
    </div>
    <div className="font-bold text-xl text-gray-800 dark:text-slate-50">{value}</div>
    <div className="text-sm text-gray-600 dark:text-slate-300">{label}</div>
  </div>
);


const BookCard = ({ book }) => {
  const [imageError, setImageError] = useState(false);
  
  // Clean and validate ISBN numbers
  const cleanIsbn = (isbn) => isbn?.replace(/[="]/g, '').trim() || '';
  
  const isbn13 = cleanIsbn(book.ISBN13);
  const isbn10 = cleanIsbn(book.ISBN);
  
  // Validate ISBN formats
  const isValidIsbn13 = (isbn) => /^\d{13}$/.test(isbn);
  const isValidIsbn10 = (isbn) => /^[\dX]{10}$/.test(isbn);
  
  // Try both ISBN13 and ISBN10 for cover URLs, using larger image size (L instead of M)
  const getCoverUrls = () => {
    const urls = [];
    if (isValidIsbn13(isbn13)) {
      urls.push(`https://covers.openlibrary.org/b/isbn/${isbn13}-L.jpg`);
    }
    if (isValidIsbn10(isbn10)) {
      urls.push(`https://covers.openlibrary.org/b/isbn/${isbn10}-L.jpg`);
    }
    return urls;
  };
  
  const coverUrls = getCoverUrls();
  const [currentUrlIndex, setCurrentUrlIndex] = useState(0);
  const currentCoverUrl = coverUrls[currentUrlIndex];
  
  const handleImageError = () => {
    // Try next URL if available, otherwise show fallback
    if (currentUrlIndex < coverUrls.length - 1) {
      setCurrentUrlIndex(currentUrlIndex + 1);
    } else {
      setImageError(true);
    }
  };
  
  const handleImageLoad = (e) => {
    // Check if image size is suspiciously small (likely a blank placeholder)
    if (e.target.naturalWidth < 50 || e.target.naturalHeight < 50) {
      handleImageError();
    } 
  };
  
  const FallbackCover = () => (
    <div className="w-full h-full flex flex-col items-center justify-center bg-gradient-to-br from-purple-100 to-indigo-100 dark:from-slate-800 dark:to-slate-900 p-4">
      <Book className="w-12 h-12 text-purple-600 dark:text-violet-400 mb-4" />
      <div className="text-center">
        <h3 className="font-semibold text-gray-800 dark:text-slate-50 text-sm line-clamp-3 mb-2">{book.Title}</h3>
        <p className="text-xs text-gray-600 dark:text-slate-300 line-clamp-2">{book.Author}</p>
      </div>
      {book['Year Published'] && (
        <div className="mt-2 text-xs text-purple-600 dark:text-violet-400 font-medium">
          {book['Year Published']}
        </div>
      )}
    </div>
  );
  
  return (
    <div className="bg-white dark:bg-slate-800/50 rounded-lg overflow-hidden shadow-md hover:shadow-lg transition-all duration-300 border border-purple-100 dark:border-violet-500/20 backdrop-blur-sm">
      <div className="aspect-[2/3] relative">
        {!imageError && currentCoverUrl ? (
          <img
            src={currentCoverUrl}
            alt={book.Title}
            className="w-full h-full object-cover"
            onError={() => setImageError(true)}
            onLoad={handleImageLoad}
          />
        ) : (
          <FallbackCover />
        )}
        {book['My Rating'] > 0 && (
          <div className="absolute top-2 right-2 bg-white dark:bg-slate-800 px-2 py-1 rounded-full text-sm font-medium text-purple-600 dark:text-violet-400 shadow-sm">
            {book['My Rating']}/5
          </div>
        )}
      </div>
      <div className="p-4">
        <h4 className="font-semibold text-gray-800 dark:text-slate-50 line-clamp-2 mb-1">{book.Title}</h4>
        <p className="text-sm text-gray-600 dark:text-slate-300 mb-2">{book.Author}</p>
        <div className="flex items-center justify-between text-sm text-gray-500 dark:text-slate-400">
          <span className="flex items-center gap-1">
            <Calendar className="w-4 h-4" />
            {book['Year Published']}
          </span>
          <span className="text-purple-600 dark:text-violet-400">
            {book['Date Added']}
          </span>
        </div>
      </div>
    </div>
  );
};

const ReadingStats = ({ stats }) => (
  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
    <StatsCard icon={BookOpen} value={stats.totalBooks} label="Total Books" />
    <StatsCard icon={Star} value={stats.averageRating.toFixed(1)} label="Avg Rating" />
    <StatsCard icon={Library} value={stats.totalGenres} label="Genres Explored" />
    <StatsCard icon={Clock} value={stats.readBooks} label="Books Read" />
  </div>
);

const GenreDistribution = ({ genres }) => (
  <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
    {Object.entries(genres)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 9)
      .map(([genre, count]) => (
        <div key={genre} className="bg-white dark:bg-slate-800/50 rounded-lg p-4 shadow-sm border border-purple-100 dark:border-violet-500/20 backdrop-blur-sm">
          <div className="text-sm text-gray-600 dark:text-slate-300 mb-1">{genre}</div>
          <div className="flex items-center justify-between">
            <div className="font-semibold text-gray-800 dark:text-slate-50">{count} books</div>
            <div className="w-24 bg-purple-100 dark:bg-violet-500/20 rounded-full h-2">
              <div
                className="bg-gradient-to-r from-purple-500 to-indigo-500 dark:from-violet-500 dark:to-fuchsia-500 h-2 rounded-full"
                style={{ width: `${(count / Math.max(...Object.values(genres))) * 100}%` }}
              />
            </div>
          </div>
        </div>
      ))}
  </div>
);

const Pagination = ({ currentPage, totalPages, onPageChange }) => (
  <div className="flex items-center justify-center gap-2 mt-6">
    <button
      onClick={() => onPageChange(currentPage - 1)}
      disabled={currentPage === 1}
      className="p-2 rounded-lg hover:bg-purple-50 dark:hover:bg-violet-500/20 disabled:opacity-50 disabled:cursor-not-allowed"
    >
      <ChevronLeft className="w-5 h-5 text-purple-600 dark:text-violet-400" />
    </button>
    
    <div className="flex items-center gap-1">
      {Array.from({ length: totalPages }, (_, i) => i + 1).map((page) => (
        <button
          key={page}
          onClick={() => onPageChange(page)}
          className={`w-8 h-8 rounded-lg text-sm font-medium transition-colors ${
            currentPage === page
              ? 'bg-gradient-to-r from-purple-600 to-indigo-600 dark:from-violet-500 dark:to-fuchsia-500 text-white'
              : 'text-gray-600 dark:text-slate-300 hover:bg-purple-50 dark:hover:bg-violet-500/20'
          }`}
        >
          {page}
        </button>
      ))}
    </div>

    <button
      onClick={() => onPageChange(currentPage + 1)}
      disabled={currentPage === totalPages}
      className="p-2 rounded-lg hover:bg-purple-50 dark:hover:bg-violet-500/20 disabled:opacity-50 disabled:cursor-not-allowed"
    >
      <ChevronRight className="w-5 h-5 text-purple-600 dark:text-violet-400" />
    </button>
  </div>
);


const LiteraryOdyssey = () => {
  const [books, setBooks] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [stats, setStats] = useState({
    totalBooks: 0,
    averageRating: 0,
    totalGenres: 0,
    readBooks: 0,
    genres: {}
  });

  const BOOKS_PER_PAGE = 10;

  useEffect(() => {
    const fetchBooks = async () => {
      try {
        const response = await fetch(`${window.location.href}data/books.json`);
        const books = await response.json();
        setBooks(books);

        // Calculate stats
        const genres = books.reduce((acc, book) => {
          if (book.Bookshelves) {
            book.Bookshelves.split(',').forEach(shelf => {
              const cleanShelf = shelf.trim();
              acc[cleanShelf] = (acc[cleanShelf] || 0) + 1;
            });
          }
          return acc;
        }, {});

        const ratedBooks = books.filter(book => book['My Rating'] > 0);
        const readBooks = books.filter(book => book['Exclusive Shelf'] === 'read').length;

        setStats({
          totalBooks: books.length,
          averageRating: ratedBooks.length > 0 
            ? ratedBooks.reduce((acc, book) => acc + book['My Rating'], 0) / ratedBooks.length 
            : 0,
          totalGenres: Object.keys(genres).length,
          readBooks,
          genres
        });
      } catch (error) {
        console.error('Error loading books:', error);
      }
    };

    fetchBooks();
  }, []);

  const topRatedBooks = _.orderBy(
    books.filter(book => book['My Rating'] === 5),
    ['Date Read'],
    ['desc']
  ).slice(0, 5);

  const recentlyRead = _.orderBy(
    books.filter(book => book['Exclusive Shelf'] === 'read'),
    ['Date Read'],
    ['desc']
  ).slice(0, 6);

  // Calculate pagination
  const totalPages = Math.ceil(books.length / BOOKS_PER_PAGE);
  const paginatedBooks = _.chunk(
    _.orderBy(books, ['Date Added'], ['desc']),
    BOOKS_PER_PAGE
  )[currentPage - 1] || [];

  return (
    <ThemedSection title="My Bookshelf" icon={Book}>
      {/* Reading Stats */}
      <ThemedCard
        title="Reading Journey"
        subtitle="A snapshot of my reading adventures"
        icon={BarChart3}
        className="mb-8"
      >
        <ReadingStats stats={stats} />
      </ThemedCard>

      {/* Book Shelf - All Books */}
      <ThemedCard
        title="Book Shelf"
        subtitle="My complete collection of literary adventures"
        icon={BookOpen}
        className="mb-8"
      >
        <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
          {paginatedBooks.map((book, index) => (
            <BookCard key={index} book={book} />
          ))}
        </div>
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={setCurrentPage}
        />
      </ThemedCard>

      {/* 5-Star Reads */}
      <ThemedCard
        title="5-Star Favorites"
        subtitle="Books that earned my highest rating"
        icon={Award}
        className="mb-8"
      >
        <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
          {topRatedBooks.map((book, index) => (
            <BookCard key={index} book={book} />
          ))}
        </div>
      </ThemedCard>

      {/* Genre Distribution */}
      <ThemedCard
        title="Genre Explorer"
        subtitle="My literary interests across different genres"
        icon={Library}
        className="mb-8"
      >
        <GenreDistribution genres={stats.genres} />
      </ThemedCard>

      {/* Recent Reads */}
      <ThemedCard
        title="Recent Adventures"
        subtitle="My latest completed reads"
        icon={BookOpen}
      >
        <div className="grid grid-cols-2 md:grid-cols-6 gap-4">
          {recentlyRead.map((book, index) => (
            <BookCard key={index} book={book} />
          ))}
        </div>
      </ThemedCard>
    </ThemedSection>
  );
};

export default LiteraryOdyssey;